const input = $('다른 워크플로우에서 호출').first().json;
const s = input.settings || {};
const positive = (v, fallback) => (Number(v) > 0 ? Number(v) : fallback);
const opt = {
  topN: positive(s.topN, 10),
  minVolRatio: positive(s.minVolRatio, 1.5),
  maxRsi: positive(s.maxRsi, 70),
  vixCaution: positive(s.vixCaution, 25),
};
const round = (x, d = 2) => (x === null || x === undefined || !Number.isFinite(x)) ? null : Math.round(x * 10 ** d) / 10 ** d;
const avg = (arr) => arr.reduce((a, b) => a + b, 0) / arr.length;
const clamp01 = (x) => Math.max(0, Math.min(1, x));

// RSI(14), Wilder 방식
function rsi(closes, period = 14) {
  if (closes.length <= period) return null;
  let gain = 0;
  let loss = 0;
  for (let i = 1; i <= period; i++) {
    const change = closes[i] - closes[i - 1];
    if (change > 0) gain += change; else loss -= change;
  }
  let avgGain = gain / period;
  let avgLoss = loss / period;
  for (let i = period + 1; i < closes.length; i++) {
    const change = closes[i] - closes[i - 1];
    avgGain = (avgGain * (period - 1) + Math.max(change, 0)) / period;
    avgLoss = (avgLoss * (period - 1) + Math.max(-change, 0)) / period;
  }
  if (avgLoss === 0) return 100;
  return 100 - 100 / (1 + avgGain / avgLoss);
}

// 날짜별 시세를 종목별 시계열로 묶음
const candidates = new Map((input.candidates || []).map(c => [c.code, c]));
const byCode = new Map();
for (const day of input.days || []) {
  for (const r of day.rows || []) {
    if (!candidates.has(r.code) || !(r.close > 0)) continue;
    if (!byCode.has(r.code)) byCode.set(r.code, new Map());
    byCode.get(r.code).set(day.date, r);
  }
}

const passed = [];
let evaluated = 0;
let skipped = 0;
for (const [code, byDate] of byCode) {
  const series = [...byDate.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([date, r]) => ({ ...r, date }));
  const n = series.length;
  // 60일 이동평균에 61거래일이 필요하고, 기준일에 거래가 있어야 함
  if (n < 61 || series[n - 1].date !== input.baseDate) {
    skipped++;
    continue;
  }
  evaluated++;
  const closes = series.map(r => r.close);
  const volumes = series.map(r => r.volume);
  const last = series[n - 1];
  const ma20 = avg(closes.slice(-20));
  const ma60 = avg(closes.slice(-60));
  const rsi14 = rsi(closes);
  const volume20 = avg(volumes.slice(-21, -1));
  const volRatio = volume20 > 0 ? last.volume / volume20 : null;

  const ok = last.close > ma20
    && ma20 > ma60
    && volRatio !== null && volRatio >= opt.minVolRatio
    && rsi14 !== null && rsi14 < opt.maxRsi;
  if (!ok) continue;

  // 점수(100점): 거래량 40 + 추세 30 + RSI 30
  const score = 40 * clamp01(volRatio / 3)
    + 30 * clamp01((ma20 / ma60 - 1) / 0.1)
    + 30 * clamp01(1 - Math.abs(rsi14 - 60) / 20);
  const info = candidates.get(code) || {};
  passed.push({
    code,
    name: info.name || last.name || code,
    board: info.board || last.board || '',
    close: last.close,
    change1dPct: round((closes[n - 1] / closes[n - 2] - 1) * 100),
    change5dPct: round((closes[n - 1] / closes[n - 6] - 1) * 100),
    vsMa20Pct: round((last.close / ma20 - 1) * 100),
    ma20OverMa60Pct: round((ma20 / ma60 - 1) * 100),
    rsi14: round(rsi14, 1),
    volRatio: round(volRatio),
    value: Math.round(last.value || 0),
    score: round(score, 1),
  });
}
passed.sort((a, b) => b.score - a.score);

// 시장이 불안하면 선정 수를 절반으로 줄임
const ind = input.indicators || {};
const cautionReasons = [];
const vix = ind.us && ind.us.vix ? ind.us.vix.value : null;
if (Number.isFinite(vix) && vix >= opt.vixCaution) cautionReasons.push(`VIX ${vix} (기준 ${opt.vixCaution} 이상)`);
const kospi = ind.kr && ind.kr.kospi ? ind.kr.kospi.vsMa20Pct : null;
if (Number.isFinite(kospi) && kospi < 0) cautionReasons.push(`KOSPI가 20일 평균보다 ${Math.abs(kospi)}% 아래`);
const usdKrw = ind.fx && ind.fx.usdKrw ? ind.fx.usdKrw.changePct : null;
if (Number.isFinite(usdKrw) && usdKrw >= 1) cautionReasons.push(`원/달러 환율 하루 ${usdKrw}% 상승`);
const topN = cautionReasons.length ? Math.max(1, Math.ceil(opt.topN / 2)) : opt.topN;
const picks = passed.slice(0, topN).map((p, i) => ({ rank: i + 1, ...p }));

return [{
  json: {
    picks,
    meta: {
      market: input.market,
      marketLabel: input.marketLabel,
      baseDate: input.baseDate,
      candidateCount: candidates.size,
      evaluated,
      skipped,
      passed: passed.length,
      topN,
      caution: cautionReasons.length > 0,
      cautionReasons,
      criteria: `종가 > 20일 평균, 20일 평균 > 60일 평균, 거래량 ≥ 20일 평균의 ${opt.minVolRatio}배, RSI(14) < ${opt.maxRsi}`,
    },
  },
}];

